import type {Provider} from '@github-ui/copilot-byok/providers'
import {FormControl, Stack} from '@primer/react'
import {useId} from 'react'
import * as z from 'zod'

import styles from '../AddEditDialog.module.css'
import {FormValidationNode} from '../FormValidationNode'
import {ProviderModelSelectorPane} from './ProviderModelSelectorPane'
import type {ProviderFieldProps} from './types'

export const genericProviderFormSchema = {
  provider: z.enum(['openai', 'anthropic', 'xai', 'googleaistudio']),
  models: z.array(
    z.union([
      z.object({
        id: z.number(),
        name: z.string().nullish(),
      }),
      z.object({
        slug: z.string(),
        name: z.string().nullish(),
      }),
    ]),
    'Please select a model',
  ),
} as const

export function GenericProviderFields<P extends Provider>({
  apiKey,
  customKey,
  provider,
  validation,
  setValidation,
  isPending,
  onSetAdditionalData,
  org,
  onUpdateModel,
}: ProviderFieldProps<P> & {provider: P}) {
  const id = useId()
  const htmlForId = `${id}-model-selector`
  const ariaDescribedBy = `${id}-description`

  return (
    <Stack.Item grow className={styles.ModelSelectorLayout}>
      <FormControl className="width-full" disabled={isPending}>
        <FormControl.Label htmlFor={htmlForId}>Available models</FormControl.Label>
        <ProviderModelSelectorPane
          provider={provider}
          customKeyId={customKey?.id}
          key={apiKey}
          apiKey={apiKey}
          isPending={isPending}
          htmlForId={htmlForId}
          aria-describedby={ariaDescribedBy}
          setValidation={setValidation}
          onSetAdditionalData={onSetAdditionalData}
          customKeyName={customKey?.name}
          org={org}
          onUpdateModel={onUpdateModel}
        />
        <FormValidationNode item={validation?.models} id={ariaDescribedBy} />
      </FormControl>
    </Stack.Item>
  )
}
